package kz.bekzat.jwt.export;
import kz.bekzat.jwt.dao.SecurityEventDao;import org.springframework.stereotype.Service;import java.nio.file.*;
@Service public class CsvExportService {private final SecurityEventDao dao;public CsvExportService(SecurityEventDao d){dao=d;}public Path export(Path path)throws java.io.IOException{if(path.getParent()!=null)Files.createDirectories(path.getParent());StringBuilder b=new StringBuilder("eventType,username,description,ipAddress,timestamp\n");for(var e:dao.findAll())b.append(cell(e.eventType())).append(',').append(cell(e.username())).append(',').append(cell(e.description())).append(',').append(cell(e.ipAddress())).append(',').append(cell(e.timestamp().toString())).append('\n');return Files.writeString(path,b.toString());}private String cell(String s){return s==null?"\"\"":"\""+s.replace("\"","\"\"")+"\"";}}
